        "May": 5, "Jun": 6, "Jul": 7, "Aug": 8,
        "Sep": 9, "Oct": 10, "Nov": 11, "Dec": 12,
    }

    def parse_date(value):
        value = value.strip()

        try:
            if re.fullmatch(r"\d{2}/\d{2}/\d{4}", value):
                return datetime.strptime(value, "%d/%m/%Y").date().isoformat()

            if re.fullmatch(r"\d{4}-\d{2}-\d{2}", value):
                return datetime.strptime(value, "%Y-%m-%d").date().isoformat()
        except ValueError:
            return None

        match = re.fullmatch(r"(\d{1,2}) ([A-Za-z]{3}) (\d{4})", value)
        if match:
            day, month, year = match.groups()
            month = month.title()
            if month in month_map:
                try:
                    return datetime(int(year), month_map[month], int(day)).date().isoformat()
                except ValueError:
                    pass

        return None

    def parse_amount(value):
        value = value.strip()
        number = r"(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?"

        match = re.fullmatch(rf"[₹$]\s*\(({number})\)", value)
        if match:
            return -float(match.group(1).replace(",", ""))

        match = re.fullmatch(rf"\(({number})\)", value)
        if match:
            return -float(match.group(1).replace(",", ""))

        match = re.fullmatch(rf"[₹$]\s*({number})(?:\s+DR)?", value)
        if match:
            return float(match.group(1).replace(",", "")) * (
                -1 if value.upper().endswith(" DR") else 1
            )

        match = re.fullmatch(rf"({number})(?:\s+DR)?", value)
        if match:
            return float(match.group(1).replace(",", "")) * (
                -1 if value.upper().endswith(" DR") else 1
            )

        return None

    results = []

    for line in text.splitlines():
        if not line.strip():
            continue

        parts = line.split(",")
        if len(parts) != 3:
            continue

        date = parse_date(parts[0])
        amount = parse_amount(parts[2])
        if date is None or amount is None:
            continue

        results.append({
            "date": date,
            "description": parts[1].strip(),
            "amount": amount,
        })

    results.sort(key=lambda item: item["date"])
    return results

