            current = self._parent[current]

        for node in ancestors:
            elapsed = max(0.0, now - self._last_seen[node])
            self._tokens[node] = min(
                self._capacity[node],
                self._tokens[node] + elapsed * self._refill_rate[node],
            )
            if now > self._last_seen[node]:
                self._last_seen[node] = now

        if any(self._tokens[node] < n for node in ancestors):
            return False

        for node in ancestors:
            self._tokens[node] -= n

        return True

