def split_bill(amounts, n):
    from decimal import Decimal

    decimals = [Decimal(value) for value in amounts]
    if not isinstance(n, int) or n <= 0:
        raise ValueError("n must be a positive integer")

    if any(not value.is_finite() or value < 0 for value in decimals):
        raise ValueError("amounts must be non-negative finite decimal strings")

    scale = max((max(0, -value.as_tuple().exponent) for value in decimals), default=0)
    total_units = 0

    for value in decimals:
        sign, digits, exponent = value.as_tuple()
        coefficient = 0
        for digit in digits:
            coefficient = coefficient * 10 + digit
        total_units += coefficient * 10 ** (exponent + scale)

    if scale <= 2:
        total_cents = total_units * 10 ** (2 - scale)
    else:
        divisor = 10 ** (scale - 2)
        total_cents, remainder = divmod(total_units, divisor)
        if remainder * 2 > divisor or (
            remainder * 2 == divisor and total_cents % 2 == 1
        ):
            total_cents += 1

    base, extra = divmod(total_cents, n)
    return [
        f"{(base + (i < extra)) // 100}.{(base + (i < extra)) % 100:02d}"
        for i in range(n)
    ]

def split_bill(amounts, n):
    from decimal import Decimal

    if not amounts:
        total_cents = 0
    else:
        values = [Decimal(amount).as_tuple() for amount in amounts]
        min_exp = min(exp for _, _, exp in values)
        total_units = 0

        for sign, digits, exp in values:
            coefficient = int("".join(map(str, digits)) or "0")
            if sign:
                coefficient = -coefficient
            total_units += coefficient * 10 ** (exp - min_exp)

        scale = min_exp + 2
        if scale >= 0:
            total_cents = total_units * 10 ** scale
        else:
            divisor = 10 ** (-scale)
            total_cents, remainder = divmod(total_units, divisor)
            if remainder * 2 > divisor or (
                remainder * 2 == divisor and total_cents % 2 == 1
            ):
                total_cents += 1

    base, extra = divmod(total_cents, n)
    return [
        f"{base + (i < extra) ://100}.{(base + (i < extra)) % 100:02d}"
        for i in range(n)
    ]

def truncate_graphemes(s, n):
    import unicodedata

    clusters = []
    join_next = False

    for char in s:
        category = unicodedata.category(char)

        if category == "Mn":
            if clusters:
                clusters[-1] += char
            else:
                clusters.append(char)
            join_next = False
        elif char == "\u200d":
            if clusters:
